    "machine_cost_per_h = 0.5",
    "jobs = 100"
  ],
  "assumptions": [
    "Attempts are independent with the same failure probability; repeat until one succeeds (geometric).",
    "Unmonitored failures are found at the end of the job and waste its full time and filament.",
    "A detected failure stops the printer delay minutes after it happens at mean_failure_point of the job.",
    "Detect-and-adapt: recoverable_share of failures finish as a usable part with no extra waste. This share is the project's hypothesis, not a measured value.",
    "Waste cost = filament + machine time; staff time is not counted."
  ],
  "warnings": [],
  "human_checks": [
    "Replace the default failure probability with your printer's own record.",
    "recoverable_share is the project's hypothesis, not a measured value."
  ]
}

{
  "tool": "plan_unattended_print",
  "verdict": "CAUTION",
  "decision": "start at 08:00",
  "summary": "A 14 h job started at 22:30 finishes at 12:30 (+1 d); 61% of it runs unattended. If it fails (15% chance), on average 1.6 h pass before anyone knows; expected waste for this attempt is 16.9 g and 0.79 printer-hours ($0.78). Best start in your window: 08:00 (expected waste $0.61).",
  "results": {
    "finish_time": {
      "label": "Finish time (clock)",
      "value": "12:30 (+1 d)",
      "unit": "HH:MM"
    },
    "unattended_share_pct": {
      "label": "Share of the print that runs unattended",
      "value": 61.0,
      "unit": "%"
    },
    "unattended_hours": {
      "label": "Unattended printing hours",
      "value": 8.51,
      "unit": "h"
    },
    "p_failure_while_unattended_pct": {
      "label": "If it fails: chance the failure happens while nobody is there",
      "value": 30.0,
      "unit": "%"
    },
    "mean_hours_until_known": {
      "label": "If it fails: mean time until someone knows",
      "value": 1.64,
      "unit": "h"
    },
    "mean_idle_hours_after_stop": {
      "label": "If it fails: mean idle printer time before it can be restarted",
      "value": 0.0,
      "unit": "h"
    },
    "worst_case_hours_unseen": {
      "label": "Worst case: longest a failure can go unnoticed",
      "value": 8.5,
      "unit": "h"
    },
    "expected_wasted_filament_g": {
      "label": "Expected wasted filament for this attempt",
      "value": 16.9,
      "unit": "g"
    },
    "expected_wasted_hours": {
      "label": "Expected wasted printer hours for this attempt",
      "value": 0.79,
      "unit": "h"
    },
    "expected_waste_cost_usd": {
      "label": "Expected waste cost for this attempt",
      "value": 0.78,
      "unit": "$"
    },
    "recommended_start": {
      "label": "Recommended start time in your window",
      "value": "08:00",
      "unit": "HH:MM"
    },
    "recommended_finish": {
      "label": "Finish time with the recommended start",
      "value": "22:00",
      "unit": "HH:MM"
    },
    "recommended_expected_waste_cost_usd": {
      "label": "Expected waste cost with the recommended start",
      "value": 0.61,
      "unit": "$"
    },
    "recommended_mean_hours_until_known": {
      "label": "Mean time until a failure is known, recommended start",
      "value": 0.5,
      "unit": "h"
    }
  },
  "checks": [
    {
      "name": "First layers watched",
      "status": "OK",
      "detail": "The first 0.5 h (where 50% of failures are assumed to happen) runs while you are present."
    },
    {
      "name": "Unseen failure time",
      "status": "OK",
      "detail": "If it fails, on average 1.6 h pass before anyone knows (CAUTION above 2 h)."
    },
    {
      "name": "No automatic stop",
      "status": "CAUTION",
      "detail": "61% of the print runs unattended with nothing that can stop a failure."
    }
  ],
  "features": null,
  "inputs": {
    "print_time_h": 14.0,
    "filament_g": 300.0,
    "start_time": "22:30",
    "away_from": "23:30",
    "back_at": "08:00",
    "detection": "none",
    "failure_probability": 0.15,
    "early_failure_share": 0.5,
    "early_window_h": 0.5,
    "detection_coverage": null,
    "detection_delay_min": null,
    "check_interval_min": 60.0,
    "filament_price_per_kg": 23.0,
    "machine_cost_per_h": 0.5,
    "earliest_start": "08:00",
    "latest_start": "23:00"
  },
  "defaults_used": [
    "failure_probability = 0.15",
    "early_failure_share = 0.5",
    "early_window_h = 0.5",
    "check_interval_min = 60",
    "filament_price_per_kg = 23",
    "machine_cost_per_h = 0.5"
  ],
  "assumptions": [
    "One attempt fails with probability failure_probability; early_failure_share of failures happen in the first early_window_h (bed adhesion), the rest uniformly over the job. Both are assumptions, not data.",
    "While present you notice a failure at your next look (half of check_interval_min on average); while away, when you come back. The same away window repeats every day.",
    "A failed job keeps extruding (spaghetti) until it is stopped or the G-code ends; the whole attempt is restarted, never resumed.",
    "Auto-stop catches detection_coverage of failures detection_delay_min after they start; the rest behave as with no detection.",
    "Waste cost = filament + machine time; staff time, energy for re-heating and hardware damage are not counted."
  ],
  "warnings": [
    "Hardware damage (a jammed or cracked nozzle) and fire risk are not modelled; follow your space's rules on unattended printing."
  ],
  "human_checks": [
    "Watch the first layer yourself (or check the camera) before leaving, whatever the tool says.",
    "Check that unattended printing is allowed in your space and that the printer has thermal-runaway protection.",
    "Replace the default failure_probability with your own printer's record if you have one."
  ]
}

{
  "tool": "check_deviated_part",
  "verdict": "CAUTION",
  "decision": "TEST_BEFORE_USE",
  "summary": "Decision: TEST_BEFORE_USE, because layers were changed in the load path, so a calculation alone cannot vouch for its strength. 3 feature(s) checked, 0 functional feature(s) out of tolerance; arm safety factor 3.35 as printed.",
  "results": {
    "beam_safety_factor_design": {
      "label": "Arm safety factor, design thickness",
      "value": 4.14,
      "unit": "-"
    },
    "beam_safety_factor_as_printed": {
      "label": "Arm safety factor, as-printed thickness",
      "value": 3.35,
      "unit": "-"
    },
    "beam_strength_retained_pct": {
      "label": "Bending strength retained (∝ thickness²)",
      "value": 81.0,
      "unit": "%"
    },
    "beam_breaking_load_as_printed_N": {
      "label": "Estimated breaking load, as printed",
      "value": 65.8,
      "unit": "N"
    },
    "beam_tip_deflection_as_printed_mm": {
      "label": "Tip deflection, as printed",
      "value": 1.03,
      "unit": "mm"
    },
    "reprint_cost_usd": {
      "label": "Cost of a reprint (filament + machine time)",
      "value": 2.12,
      "unit": "$"
    },
    "reprint_time_h": {
      "label": "Printer time for a reprint",
      "value": 2.5,
      "unit": "h"
    },
    "features_checked": {
      "label": "Features checked",
      "value": 3.0,
      "unit": "-"
    },
    "features_out_of_tolerance": {
      "label": "Fit/load-bearing features out of tolerance",
      "value": 0.0,
      "unit": "-"
    },
    "worst_functional_tolerance_used_pct": {
      "label": "Tolerance used by the tightest functional feature (arm thickness)",
      "value": 83.0,
      "unit": "%"
    }
  },
  "checks": [
    {
      "name": "Dimensions within designer tolerances",
      "status": "OK",
      "detail": "all features within tolerance."
    },
    {
      "name": "Load-bearing arm, as printed",
      "status": "OK",
      "detail": "Safety factor 3.35 as printed vs 4.14 as designed (target 2)."
    },
    {
      "name": "Repair in the load path",
      "status": "CAUTION",
      "detail": "Layers were changed or re-started where load passes; the bond there is unknown, so the calculated safety factor is not enough on its own."
    }
  ],
  "features": [
    {
      "name": "outer shell",
      "role": "cosmetic",
      "nominal_mm": 40.0,
      "measured_mm": 40.6,
      "deviation_mm": 0.6,
      "tolerance_mm": 1.0,
      "tolerance_used_pct": 60.0,
      "status": "OK"
    },
    {
      "name": "M5 mounting hole",
      "role": "fit",
      "nominal_mm": 5.3,
      "measured_mm": 5.22,
      "deviation_mm": -0.08,
      "tolerance_mm": 0.15,
      "tolerance_used_pct": 53.0,
      "status": "OK"
    },
    {
      "name": "arm thickness",
      "role": "load_bearing",
      "nominal_mm": 5.0,
      "measured_mm": 4.5,
      "deviation_mm": -0.5,
      "tolerance_mm": 0.6,
      "tolerance_used_pct": 83.0,
      "status": "OK"
    }
  ],
  "inputs": {
    "features": [
      {
        "name": "outer shell",
        "role": "cosmetic",
        "nominal_mm": 40.0,
        "measured_mm": 40.6,
        "tolerance_mm": 1.0
      },
      {
        "name": "M5 mounting hole",
        "role": "fit",
        "nominal_mm": 5.3,
        "measured_mm": 5.22,
        "tolerance_mm": 0.15
      },
      {
        "name": "arm thickness",
        "role": "load_bearing",
        "nominal_mm": 5.0,
        "measured_mm": 4.5,
        "tolerance_mm": 0.6
      }
    ],
    "beam": {
      "material": "PLA",
      "length_mm": 40.0,
      "width_mm": 20.0,
      "nominal_thickness_mm": 5.0,
      "measured_thickness_mm": 4.5,
      "load_kg": 2.0,
      "orientation": "flat"
    },
    "repaired_in_load_path": true,
    "reprint_time_h": 2.5,
    "reprint_filament_g": 38.0
  },
  "defaults_used": [
    "outer shell: tolerance_mm = 1.0 (cosmetic default)",
    "beam: target_safety_factor = 2.0",
    "beam: interlayer_factor = 0.5",
    "filament_price_per_kg = 23",
    "machine_cost_per_h = 0.5"
  ],
  "assumptions": [
    "A feature passes when |measured − nominal| ≤ tolerance_mm; tolerances come from the designer.",
    "Cosmetic features (shells, outer walls) default to ±1 mm and can only give a CAUTION.",
    "The arm check reuses check_cantilever with the measured thickness; it assumes a solid section and the same material and layer bonding as the design, which a repaired region may not have.",
    "The tool judges geometry and calculated strength only, not surface finish, porosity or material behaviour."
  ],
  "warnings": [],
  "human_checks": [
    "Measure the features yourself (calipers or a test fit); the tool trusts the numbers it is given.",
    "For TEST_BEFORE_USE, proof-load the part to the target load (or a sacrificial copy) before relying on it.",
    "Confirm the tolerances with whoever designed the part."
  ]
}
